import numpy as np

def relu(x):
    return np.maximum(0, x)

def compute_loss_and_grad(params, X, Y):
    W, b = params['W'], params['b']
    pred = X @ W + b
    error = pred - Y
    n = len(Y)
    loss = np.mean(error**2)
    dW = 2/n * X.T @ error
    db = 2/n * np.sum(error)
    return loss, {'W': dW, 'b': db}

def copy_params(params):
    return {k: v.copy() for k, v in params.items()}

def reptile_inner_loop(params, task_data, inner_lr, n_inner_steps):
    theta = copy_params(params)
    X, Y = task_data['support_x'], task_data['support_y']
    for _ in range(n_inner_steps):
        _, grad = compute_loss_and_grad(theta, X, Y)
        theta['W'] = theta['W'] - inner_lr * grad['W']
        theta['b'] = theta['b'] - inner_lr * grad['b']
    return theta

def reptile_meta_update(initial_params, adapted_params, meta_lr):
    updated = {}
    for key in initial_params:
        direction = adapted_params[key] - initial_params[key]
        updated[key] = initial_params[key] + meta_lr * direction
    return updated

def sample_sinusoidal_task(n_support=10):
    amplitude = np.random.uniform(0.1, 5.0)
    phase = np.random.uniform(0, np.pi)
    x = np.random.uniform(-5, 5, n_support).reshape(-1, 1)
    y = amplitude * np.sin(x + phase)
    return {'support_x': x, 'support_y': y, 'amplitude': amplitude, 'phase': phase}

def reptile_train(n_iterations=1000, n_tasks_per_iter=10, inner_lr=0.02, meta_lr=0.001, n_inner_steps=5):
    params = {'W': np.random.randn(1, 1) * 0.01, 'b': np.array([0.0])}
    for iteration in range(n_iterations):
        accumulated_direction = {'W': np.zeros_like(params['W']), 'b': np.zeros_like(params['b'])}
        for _ in range(n_tasks_per_iter):
            task = sample_sinusoidal_task()
            adapted = reptile_inner_loop(params, task, inner_lr, n_inner_steps)
            for key in params:
                accumulated_direction[key] += adapted[key] - params[key]
        for key in params:
            accumulated_direction[key] /= n_tasks_per_iter
            params[key] = params[key] + meta_lr * accumulated_direction[key]
    return params

def compare_updates(maml_update, reptile_update):
    maml_norm = np.sqrt(sum(np.sum(v**2) for v in maml_update.values()))
    reptile_norm = np.sqrt(sum(np.sum(v**2) for v in reptile_update.values()))
    dot_product = sum(np.sum(maml_update[k] * reptile_update[k]) for k in maml_update)
    similarity = dot_product / (maml_norm * reptile_norm + 1e-10)
    return {'maml_norm': maml_norm, 'reptile_norm': reptile_norm, 'cosine_similarity': similarity}

if __name__ == "__main__":
    np.random.seed(42)
    params = reptile_train(n_iterations=500, n_tasks_per_iter=10, inner_lr=0.02, meta_lr=0.001)
    print(f"Meta-learned W: {params['W']}")
    print(f"Meta-learned b: {params['b']}")
    task = sample_sinusoidal_task()
    adapted = reptile_inner_loop(params, task, inner_lr=0.01, n_inner_steps=5)
    x_test = np.array([[0.0]])
    pred = x_test @ adapted['W'] + adapted['b']
    true_y = task['amplitude'] * np.sin(0.0 + task['phase'])
    print(f"Prediction: {pred[0][0]:.4f}, True: {true_y[0][0]:.4f}")
